From 84076b2cd896899790bb618d197ba63cffe7a3e8 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 03:00:50 +0100
Subject: [PATCH] klipper: keep history off disk when it is not saved across
 sessions

With "Save history across desktop sessions" off, every copied text still
went into the on-disk database, its WAL and the data folder. Use an
in-memory database and a data folder in the runtime directory instead.

BUG: 501030
---
 klipper/autotests/historymodeltest.cpp | 13 +++--
 klipper/historymodel.cpp               | 68 +++++++++++++++++++++-----
 klipper/systemclipboard.cpp            | 15 ++++--
 klipper/systemclipboard.h              |  3 ++
 4 files changed, 77 insertions(+), 22 deletions(-)

diff --git a/klipper/autotests/historymodeltest.cpp b/klipper/autotests/historymodeltest.cpp
index ab5f919dd4..39421c1ff8 100644
--- a/klipper/autotests/historymodeltest.cpp
+++ b/klipper/autotests/historymodeltest.cpp
@@ -316,19 +316,22 @@ void HistoryModelTest::testKeepClipboardContents()
     {
         std::shared_ptr<HistoryModel> history = HistoryModel::self();
         QCOMPARE(history->rowCount(), 0);
-        dataDir.refresh();
-        QVERIFY(dataDir.exists());
-        QCOMPARE(dataDir.entryList(QDir::NoDotAndDotDot).size(), 0);
+        QDir runtimeDataDir(QStandardPaths::writableLocation(QStandardPaths::RuntimeLocation) + u"/klipper/data");
+        QVERIFY(runtimeDataDir.exists());
+        QCOMPARE(runtimeDataDir.entryList(QDir::NoDotAndDotDot).size(), 0);

         QVERIFY(history->insert(QStringLiteral("foobar")));
         QCOMPARE(history->rowCount(), 1);
         QCOMPARE(history->pendingJobs(), 1);
         QTRY_COMPARE(history->pendingJobs(), 0);
+        runtimeDataDir.refresh();
+        qDebug() << runtimeDataDir.entryList();
+        QCOMPARE(runtimeDataDir.entryList().size(), 3); // QList(".", "..", "8843d7f92416211de9ebb963ff4ce28125932878")
         dataDir.refresh();
-        qDebug() << dataDir.entryList();
-        QCOMPARE(dataDir.entryList().size(), 3); // QList(".", "..", "8843d7f92416211de9ebb963ff4ce28125932878")
+        QVERIFY(!dataDir.exists());

         setKeepClipboardContents(true);
+        QCOMPARE(history->rowCount(), 1);
     }

     qDebug() << "Stage 4";
diff --git a/klipper/historymodel.cpp b/klipper/historymodel.cpp
index 8112dadb5b..a7acd28ccc 100644
--- a/klipper/historymodel.cpp
+++ b/klipper/historymodel.cpp
@@ -9,6 +9,7 @@

 #include <algorithm>
 #include <chrono>
+#include <filesystem>
 #include <zlib.h>

 #include <QAction>
@@ -181,6 +182,29 @@ QString computeUuid(const QString &text)
     data.setText(text);
     return computeUuid(&data);
 }
+
+// don't use "appdata", klipper is also a kicker applet
+QString diskDatabaseName()
+{
+    if (qEnvironmentVariableIsSet("KLIPPER_DATABASE")) {
+        return qEnvironmentVariable("KLIPPER_DATABASE");
+    }
+    return QStandardPaths::writableLocation(QStandardPaths::GenericDataLocation) + u"/klipper/history3.sqlite";
+}
+
+QString diskDatabaseFolder()
+{
+    return QFileInfo(diskDatabaseName()).absoluteDir().absolutePath();
+}
+
+void removeDiskHistory()
+{
+    const QString databaseName = diskDatabaseName();
+    for (const QString &suffix : {u""_s, u"-wal"_s, u"-shm"_s}) {
+        QFile::remove(databaseName + suffix);
+    }
+    QDir(diskDatabaseFolder() + u"/data").removeRecursively();
+}
 }

 std::shared_ptr<HistoryModel> HistoryModel::self()
@@ -269,7 +293,6 @@ HistoryModel::~HistoryModel()
 {
     if (!m_bKeepContents) {
         m_db.close();
-        QFile(m_db.databaseName()).remove();
         QDir(m_dbFolder + u"/data").removeRecursively();
     }
 }
@@ -844,25 +867,25 @@ bool HistoryModel::insert(const QString &text)
 bool HistoryModel::loadHistory()
 {
     constexpr const char *failedLoadWarning = "Failed to load history resource. Clipboard history cannot be read.";
-    // don't use "appdata", klipper is also a kicker applet
-    if (qEnvironmentVariableIsSet("KLIPPER_DATABASE")) {
-        m_dbFolder = QFileInfo(qEnvironmentVariable("KLIPPER_DATABASE")).absoluteDir().absolutePath();
-    } else {
-        m_dbFolder = QStandardPaths::writableLocation(QStandardPaths::GenericDataLocation) + u"/klipper";
-    }
+    // When the history is not kept across sessions, nothing must be written to disk
+    const QString databaseName = m_bKeepContents ? diskDatabaseName() : u":memory:"_s;
+    m_dbFolder = m_bKeepContents ? diskDatabaseFolder() : QStandardPaths::writableLocation(QStandardPaths::RuntimeLocation) + u"/klipper";
+    m_clip->setDatabaseFolder(m_dbFolder);
     QDir dataDir(m_dbFolder + u"/data");
     dataDir.mkpath(dataDir.absolutePath());

     // Try to reuse the previous connection
-    m_db = QSqlDatabase::database(u"klipper"_s);
+    m_db = QSqlDatabase::database(u"klipper"_s, false);
     if (!m_db.isValid()) [[likely]] {
         m_db = QSqlDatabase::addDatabase(u"QSQLITE"_s, u"klipper"_s);
         m_db.setHostName(u"localhost"_s);
-        if (qEnvironmentVariableIsSet("KLIPPER_DATABASE")) {
-            m_db.setDatabaseName(qEnvironmentVariable("KLIPPER_DATABASE"));
-        } else {
-            m_db.setDatabaseName(m_dbFolder + u"/history3.sqlite");
-        }
+    }
+    if (m_db.databaseName() != databaseName) {
+        m_db.close();
+        m_db.setDatabaseName(databaseName);
+    }
+    if (!m_bKeepContents) {
+        removeDiskHistory();
     }
     if (!m_db.isOpen() && !m_db.open()) {
         qCWarning(KLIPPER_LOG) << failedLoadWarning << m_db.lastError().text();
@@ -943,6 +966,7 @@ void HistoryModel::loadSettings()
     m_bSaveImages = KlipperSettings::saveImages();
     m_bNoNullClipboard = KlipperSettings::preventEmptyClipboard();
     m_bSaveSelection = KlipperSettings::saveSelection();
+    const bool keepContentsChanged = m_db.isOpen() && m_bKeepContents != KlipperSettings::keepClipboardContents();
     m_bKeepContents = KlipperSettings::keepClipboardContents();
     m_bSynchronize = KlipperSettings::syncClipboards();
     m_bActionOnSelection = KlipperSettings::actionOnSelection();
@@ -958,6 +982,24 @@ void HistoryModel::loadSettings()
     if (!m_bKeepContents) {
         clear();
     }
+
+    if (keepContentsChanged) {
+        if (m_bKeepContents) {
+            // Move the history of this session from memory to disk
+            removeDiskHistory();
+            QSqlQuery query(m_db);
+            query.prepare(u"VACUUM INTO ?"_s);
+            query.addBindValue(diskDatabaseName());
+            query.exec();
+            std::error_code error;
+            std::filesystem::copy(QFile::encodeName(m_dbFolder + u"/data").toStdString(),
+                                  QFile::encodeName(diskDatabaseFolder() + u"/data").toStdString(),
+                                  std::filesystem::copy_options::recursive,
+                                  error);
+            QDir(m_dbFolder + u"/data").removeRecursively();
+        }
+        loadHistory();
+    }
 }

 int HistoryModel::pendingJobs() const
